-- Run only against an isolated test database after the classroom migrations.
-- Uses transaction rollback and temporary assertions; no production users are involved.
begin;
create function pg_temp.expect_failure(statement text, message_pattern text) returns void language plpgsql as $$
begin
  begin execute statement;
  exception when others then
    if sqlerrm not like '%'||message_pattern||'%' then raise; end if;
    return;
  end;
  raise exception 'Expected failure: %',message_pattern;
end $$;
create function pg_temp.check_true(value boolean, label text) returns void language plpgsql as $$ begin
  if value is distinct from true then raise exception 'Check failed: %',label; end if;
end $$;
